{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01CmkQMprSZUSy1XgmSAb4bu","type":"tool_result","content":"95\t    )\n96\t\n97\t\n98\tdef mi_compute(halstead_volume, complexity, sloc, comments):\n99\t    '''Compute the Maintainability Index (MI) given the Halstead Volume, the\n100\t    Cyclomatic Complexity, the SLOC number and the number of comment lines.\n101\t    Usually it is not used directly but instead :func:`~radon.metrics.mi_visit`\n102\t    is preferred.\n103\t    '''\n104\t    if any(metric <= 0 for metric in (halstead_volume, sloc)):\n105\t        return 100.0\n106\t    sloc_scale = math.log(sloc)\n107\t    volume_scale = math.log(halstead_volume)\n108\t    comments_scale = math.sqrt(2.46 * math.radians(comments))\n109\t    # Non-normalized MI\n110\t    nn_mi = (\n111\t        171\n112\t        - 5.2 * volume_scale\n113\t        - 0.23 * complexity\n114\t        - 16.2 * sloc_scale\n115\t        + 50 * math.sin(comments_scale)\n116\t    )\n117\t    return min(max(0.0, nn_mi * 100 / 171.0), 100.0)\n118\t\n119\t"}]},"parent_tool_use_id":null,"session_id":"378af4a1-5db3-4aa1-8161-0456a57272ab","uuid":"46a1d116-45e4-40d5-8153-377d0487f73f","timestamp":"2026-11-07T14:19:31.264Z","tool_use_result":{"type":"text","file":{"filePath":"/home/user/earshot_d2/ws/workspace/radon/metrics.py","content":"    )\n\n\ndef mi_compute(halstead_volume, complexity, sloc, comments):\n    '''Compute the Maintainability Index (MI) given the Halstead Volume, the\n    Cyclomatic Complexity, the SLOC number and the number of comment lines.\n    Usually it is not used directly but instead :func:`~radon.metrics.mi_visit`\n    is preferred.\n    '''\n    if any(metric <= 0 for metric in (halstead_volume, sloc)):\n        return 100.0\n    sloc_scale = math.log(sloc)\n    volume_scale = math.log(halstead_volume)\n    comments_scale = math.sqrt(2.46 * math.radians(comments))\n    # Non-normalized MI\n    nn_mi = (\n        171\n        - 5.2 * volume_scale\n        - 0.23 * complexity\n        - 16.2 * sloc_scale\n        + 50 * math.sin(comments_scale)\n    )\n    return min(max(0.0, nn_mi * 100 / 171.0), 100.0)\n\n","numLines":25,"startLine":95,"totalLines":158}},"tool_result_meta":[{"id":"toolu_01CmkQMprSZUSy1XgmSAb4bu","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}]}
